function sources(r){return `<details><summary>Sources & research notes</summary><p>${esc(r.status)}${r.affiliation?' · '+esc(r.affiliation):''}</p>${r.notes?`<p>${esc(r.notes)}</p>`:''}${r.auditNote?`<p>${esc(r.auditNote)}</p>`:''}${r.issues.map(i=>`<p>${esc(i.type)}${i.action?': '+esc(i.action):''}</p>`).join('')}${r.sources.filter(x=>safe(x.url)).map(x=>`<a href="${esc(safe(x.url))}" target="_blank" rel="noopener noreferrer">${esc(x.type||'Source')} ↗</a>${x.checkedOn?`<p class="source-evidence">${esc(x.evidence)} · Checked ${esc(x.checkedOn)}</p>`:''}`).join('')}</details>`;}
