function filmMatches(r,f,q){return norm([f.title,...(f.aliases||[]),r.name,...(r.aliases||[]),r.community,r.countryName,r.country,f.languages,f.medium,f.credit].filter(Boolean).join(' ')).includes(q);}
function filmItems(skipList=false){const q=norm(s.queries.films).trim();let rs=scopedRecords();if(s.filmFocus&&s.record&&!q)rs=rs.filter(r=>r.id===s.record);return rs.flatMap(r=>r.films.filter(f=>filmPasses(f)&&(skipList||filmListPasses(f))).map(f=>({r,f}))).filter(({r,f})=>!q||filmMatches(r,f,q)).sort((a,b)=>s.filmSort==='year'?(filmYear(a.f)||9999)-(filmYear(b.f)||9999)||a.f.title.localeCompare(b.f.title):a.f.title.localeCompare(b.f.title));}
function filmThumbnail(f){const media=window.ATLAS_FILM_EXPLORATION?.[f.id]||{},raw=f.thumbnailURL||f.imageURL||media.thumbnail?.url;let url='';try{if(raw){const u=new URL(raw,location.href);if(['http:','https:'].includes(u.protocol))url=u.href;}}catch{}const letters=f.title.replace(/^[^\p{L}\p{N}]+/u,'').slice(0,2).toUpperCase();return `<span class="film-thumb" aria-hidden="true">${url?`<img src="${esc(url)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:''}<span>${esc(letters)}</span></span>`;}
function renderFilmBrowser(all){const section=$('#film-browser');section.hidden=s.view!=='films';if(s.view!=='films')return;const base=filmItems(),available=new Set(base.map(x=>filmInitial(x.f)));$('#film-alphabet').innerHTML=['',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ','#'].map(letter=>`<button data-film-letter="${letter}" aria-pressed="${s.filmLetter===letter}" ${letter&&!available.has(letter)?'disabled':''}>${letter||'All'}</button>`).join('');$$('[data-film-letter]').forEach(b=>b.onclick=()=>{s.filmLetter=b.dataset.filmLetter;s.filmPage=0;renderIndex();$('#index').scrollTop=0;});const pages=Math.max(1,Math.ceil(all.length/20));$('#films-prev').disabled=s.filmPage===0;$('#films-next').disabled=s.filmPage===pages-1;$('#films-page-select').innerHTML=Array.from({length:pages},(_,i)=>`<option value="${i}" ${i===s.filmPage?'selected':''}>Page ${i+1} of ${pages}</option>`).join('');$('#film-page-range').textContent=all.length?`${s.filmPage*20+1}–${Math.min((s.filmPage+1)*20,all.length)} of ${all.length} credit entries · 20 per page`:'No matching films';$('#films-prev').onclick=()=>changeFilmPage(s.filmPage-1);$('#films-next').onclick=()=>changeFilmPage(s.filmPage+1);$('#films-page-select').onchange=e=>changeFilmPage(Number(e.target.value));$('#all-films').hidden=!s.filmFocus;$('#all-films').onclick=openFilmBrowser;}
